m=np.arange(0,61);bal=475-0.35*m;home=np.full_like(m,500,dtype=float);home[m>=12]=400;ax.plot(m,bal,label='Mortgage balance',color=BAD);ax.plot(m,home,label='Home value after shock',color=ACCENT);ax.fill_between(m,home,bal,where=bal>home,color=BAD,alpha=.18,label='Negative equity');ax.set_xlabel('Month');ax.set_ylabel('USD thousands');ax.set_title('Collateral cushion can disappear abruptly',loc='left');ax.legend(fontsize=8);ax.grid(alpha=.25)
